attempts.text:
{"quests": [
  {"no": 1, "title": "재상의 인장을 맡기다", "giver": {"npc": "세드릭 몰", "place": "린도르"},
    "steps": [
      {"action": "받기", "npc": "세드릭 몰", "place": "린도르", "item": "재상의 인장", "desc": "재상 세드릭 몰에게서 재상의 인장을 건네받는다. 왕이 직접 문서를 봉할 수 있도록 엘리안 왕에게 맡겨 두라는 부탁이다."},
      {"action": "전달", "npc": "엘리안", "place": "린도르", "item": "재상의 인장", "desc": "린도르 왕궁에서 엘리안 왕을 알현하고 재상의 인장을 맡긴다."},
      {"action": "대화", "npc": "세드릭 몰", "place": "린도르", "item": null, "desc": "인장을 맡긴 사실을 세드릭 몰에게 보고한다. 재상은 소금 해안에서 들려올 소식을 기다리고 있다."}
    ]},
  {"no": 2, "title": "바다에서 돌아오지 않은 배", "giver": {"npc": "미르네", "place": "테살 항 붉은 시장"},
    "steps": [
      {"action": "대화", "npc": "미르네", "place": "테살 항 붉은 시장", "item": null, "desc": "미르네 여관에서 선장 로자 마렌이 풍랑에 목숨을 잃었다는 소식을 듣는다. 선원들이 바다에서 건져 낸 것이 있다고 한다."},
      {"action": "받기", "npc": "미르네", "place": "테살 항 붉은 시장", "item": "남풍 해도", "desc": "미르네가 맡아 두고 있던 남풍 해도를 건네받는다. 로자 마렌이 직접 그린 소금 해안의 뱃길 지도다."}
    ]},
  {"no": 3, "title": "고원 관문으로 가는 뱃길", "giver": {"npc": "하렌드 발크", "place": "서리 관문"},
    "steps": [
      {"action": "이동", "npc": null, "place": "서리 관문 입구", "item": null, "desc": "강의 땅을 지나 서리 관문으로 간다. 소금 해안으로 기사를 보낼 뱃길을 정해야 한다."},
      {"action": "전달", "npc": "하렌드 발크", "place": "서리 관문", "item": "남풍 해도", "desc": "기사단장 하렌드 발크에게 남풍 해도를 건넨다. 그는 이 지도로 소금 해안의 암초와 물길을 확인한다."},
      {"action": "대화", "npc": "하렌드 발크", "place": "서리 관문", "item": null, "desc": "하렌드 발크와 뱃길을 의논한다. 소금 해안에서 누구에게 물때와 바람을 물어야 할지 알려 준다."}
    ]},
  {"no": 4, "title": "재상에게 돌아온 인장", "giver": {"npc": "세드릭 몰", "place": "린도르"},
    "steps": [
      {"action": "받기", "npc": "엘리안", "place": "린도르", "item": "재상의 인장", "desc": "엘리안 왕에게서 맡겨 두었던 재상의 인장을 돌려받는다."},
      {"action": "전달", "npc": "세드릭 몰", "place": "린도르", "item": "재상의 인장", "desc": "재상 세드릭 몰에게 재상의 인장을 돌려준다. 재상은 이제 왕의 이름으로 문서를 봉할 수 있게 된다."}
    ]},
  {"no": 5, "title": "철마다 바뀌는 소금 바람", "giver": {"npc": "벤토 사르", "place": "테살 항"},
    "steps": [
      {"action": "이동", "npc": null, "place": "하얀 절벽 수도원 입구", "item": null, "desc": "테살 항에서 배로 하루 거리에 있는 하얀 절벽 수도원으로 간다."},
      {"action": "대화", "npc": "이렌", "place": "하얀 절벽 수도원", "item": null, "desc": "수도원장 이렌에게 소금 해안에서 철마다 부는 바람과 물때를 묻는다. 그녀는 수도원 연대기를 근거로 대답한다."},
      {"action": "받기", "npc": "이렌", "place": "하얀 절벽 수도원", "item": "하얀 절벽 연대기", "desc": "바람과 물때가 적힌 하얀 절벽 연대기의 해당 쪽을 옮겨 적도록 허락받는다."},
      {"action": "전달", "npc": "벤토 사르", "place": "테살 항", "item": "하얀 절벽 연대기", "desc": "테살 항으로 돌아와 상단주 벤토 사르에게 바람과 물때 기록을 전한다. 소금 길드의 뱃길 계획에 쓰인다."}
    ]}
]}

{"quests": [
  {"no": 1, "title": "별철 망치의 행방", "giver": {"npc": "하렌", "place": "달빛 나루"},
    "steps": [
      {"action": "받기", "npc": "하렌", "place": "달빛 나루", "item": "별철 망치", "desc": "대장장이 하렌에게서 머리가 별철로 된 별철 망치를 건네받는다. 서리 관문의 기사단장에게 전해야 할 물건이다."},
      {"action": "이동", "npc": null, "place": "서리 관문", "item": null, "desc": "강의 땅과 회색 고원을 잇는 고갯길을 올라 서리 관문에 닿는다. 관문은 잿가지 기사단이 지킨다."},
      {"action": "전달", "npc": "하렌드 발크", "place": "서리 관문", "item": "별철 망치", "desc": "기사단장 하렌드 발크에게 별철 망치를 전한다. 관문 대장간에서 쓸 연장이다."}
    ]
  },
  {"no": 2, "title": "노파의 마지막 부탁", "giver": {"npc": "마브", "place": "달빛 나루"},
    "steps": [
      {"action": "대화", "npc": "마브", "place": "달빛 나루", "item": null, "desc": "약초상 노파 마브가 자리에 누워 기침을 한다. 388년 이스카를 빠져나온 뒤로 고향에 돌아가 본 적이 없다고 말한다."},
      {"action": "찾기", "npc": null, "place": "달빛 나루", "item": "마브의 약상자", "desc": "마브가 숨을 거두자 그녀가 남긴 나무 약상자를 찾는다. 화상과 열병에 쓰는 약초가 든 상자다."},
      {"action": "전달", "npc": "하렌", "place": "달빛 나루", "item": "마브의 약상자", "desc": "이웃 대장장이 하렌에게 약상자를 맡긴다. 마브가 남긴 유일한 물건이다."}
    ]
  },
  {"no": 3, "title": "관문의 화상", "giver": {"npc": "하렌드 발크", "place": "서리 관문"},
    "steps": [
      {"action": "받기", "npc": "하렌", "place": "달빛 나루", "item": "마브의 약상자", "desc": "하렌에게서 마브의 약상자를 받아 다시 서리 관문으로 향한다."},
      {"action": "이동", "npc": null, "place": "서리 관문", "item": null, "desc": "고갯길을 다시 올라 관문으로 간다. 불에 덴 기사들이 막사에 누워 있다."},
      {"action": "전달", "npc": "하렌드 발크", "place": "서리 관문", "item": "마브의 약상자", "desc": "하렌드 발크에게 약상자를 건넨다. 화상 치료에 쓰일 약초다."}
    ]
  },
  {"no": 4, "title": "망치의 답례", "giver": {"npc": "하렌드 발크", "place": "서리 관문"},
    "steps": [
      {"action": "받기", "npc": "하렌드 발크", "place": "서리 관문", "item": "서리 뿔피리", "desc": "하렌드 발크가 고원 들소의 뿔로 만든 서리 뿔피리를 답례로 건넨다. 위급할 때 불면 고갯길 끝까지 소리가 닿는다."},
      {"action": "이동", "npc": null, "place": "달빛 나루", "item": null, "desc": "고갯길을 내려와 강의 땅 남쪽 나루터 달빛 나루로 돌아간다."},
      {"action": "전달", "npc": "하렌", "place": "달빛 나루", "item": "서리 뿔피리", "desc": "대장장이 하렌에게 서리 뿔피리를 보여 준다. 별철 망치가 관문에 잘 닿았다는 소식도 함께 전한다."}
    ]
  },
  {"no": 5, "title": "무너지기 전의 거리", "giver": {"npc": "오렌 케이", "place": "린도르"},
    "steps": [
      {"action": "대화", "npc": "오렌 케이", "place": "린도르", "item": null, "desc": "떠돌이 학자 오렌 케이를 찾아가 이스카의 옛 거리를 묻는다. 그는 이스카의 지도를 펼쳐 들고 있다."},
      {"action": "이동", "npc": null, "place": "이스카", "item": null, "desc": "강의 땅 서쪽의 폐허 이스카로 간다. 388년 검은 역병이 덮친 뒤 아무도 다시 짓지 않은 도시다."},
      {"action": "조사", "npc": null, "place": "이스카", "item": "이스카의 지도", "desc": "무너진 거리와 지하 수로를 지도와 맞대어 살핀다. 검은 우물의 위치도 지도 위에 적혀 있다. 함부로 우물 쪽으로 다가가지는 않는다."},
      {"action": "대화", "npc": "마브", "place": "달빛 나루", "item": null, "desc": "이스카에서 살아남은 마브가 이미 세상을 떠났음을 기억하고, 그녀가 들려주었던 거리의 모습을 떠올리며 오렌의 기록과 맞춰 본다."}
    ]
  }
]}

